class ThymeleafReactiveViewTests {

    private static final String TEMPLATE_NAME = "templates/home";
    private static final Locale VIEW_LOCALE = Locale.ENGLISH;
    private static final MediaType HTML_UTF_16 = MediaType.parseMediaType("text/html;charset=UTF-16");

    private ThymeleafReactiveView view;
    private ISpringWebFluxTemplateEngine templateEngine;
    private IEngineConfiguration configuration;
    private Map<String, Object> executionAttributes;
    private ApplicationContext applicationContext;
    private ServerWebExchange exchange;
    private ServerHttpResponse response;
    private ServerHttpRequest request;
    private DataBufferFactory bufferFactory;
    private HttpHeaders responseHeaders;


    @BeforeEach
    void setUp() {

        this.view = new ThymeleafReactiveView();
        this.view.setTemplateName(TEMPLATE_NAME);
        this.view.setLocale(VIEW_LOCALE);

        this.templateEngine = mock(ISpringWebFluxTemplateEngine.class);
        this.configuration = mock(IEngineConfiguration.class);
        this.executionAttributes = new LinkedHashMap<>();
        when(this.configuration.getExecutionAttributes()).thenReturn(this.executionAttributes);
        when(this.templateEngine.getConfiguration()).thenReturn(this.configuration);
        when(this.templateEngine.getAllowedClassOverridesForViews()).thenReturn(Collections.<Class<?>>emptySet());
        when(this.templateEngine.processStream(
                anyString(), nullable(Set.class), any(IContext.class), any(DataBufferFactory.class),
                any(MediaType.class), any(Charset.class), anyInt())).thenReturn(Flux.<DataBuffer>empty());
        this.view.setTemplateEngine(this.templateEngine);

        this.applicationContext = mock(ApplicationContext.class);
        when(this.applicationContext.containsBean(anyString())).thenReturn(false);
        when(this.applicationContext.getBean(ReactiveAdapterRegistry.class))
                .thenReturn(ReactiveAdapterRegistry.getSharedInstance());
        this.view.setApplicationContext(this.applicationContext);

        this.responseHeaders = new HttpHeaders();
        this.bufferFactory = mock(DataBufferFactory.class);
        this.response = mock(ServerHttpResponse.class);
        when(this.response.getHeaders()).thenReturn(this.responseHeaders);
        when(this.response.bufferFactory()).thenReturn(this.bufferFactory);
        when(this.response.writeWith(any())).thenReturn(Mono.<Void>empty());
        when(this.response.writeAndFlushWith(any())).thenReturn(Mono.<Void>empty());

        this.request = mock(ServerHttpRequest.class);
        this.exchange = mock(ServerWebExchange.class);
        when(this.exchange.getRequest()).thenReturn(this.request);
        when(this.exchange.getResponse()).thenReturn(this.response);
        when(this.exchange.getAttributes()).thenReturn(new HashMap<String, Object>());
        when(this.exchange.getLocaleContext()).thenReturn(new SimpleLocaleContext(Locale.US));
    }


    @Test
    void defaultsAreAppliedBeforeConfiguration() {

        assertNull(this.view.getBeanName());
        assertNull(this.view.getTemplateName());
        assertNull(this.view.getMarkupSelector());
        assertNull(this.view.getNullableResponseMaxChunkSize());
        assertEquals(ThymeleafReactiveView.DEFAULT_RESPONSE_CHUNK_SIZE_BYTES,
                this.view.getResponseMaxChunkSizeBytes());
        assertTrue(this.view.getStaticVariables().isEmpty());
        assertFalse(this.view.isDefaultCharsetSet());
        assertFalse(this.view.isSupportedMediaTypesSet());
    }


    @Test
    void simplePropertiesCanBeSetAndRead() {

        this.view.setBeanName("homeView");
        this.view.setTemplateName("templates/other");
        this.view.setResponseMaxChunkSizeBytes(4096);

        assertEquals("homeView", this.view.getBeanName());
        assertEquals("templates/other", this.view.getTemplateName());
        assertEquals(4096, this.view.getResponseMaxChunkSizeBytes());
        assertEquals(Integer.valueOf(4096), this.view.getNullableResponseMaxChunkSize());
    }


    @Test
    void markupSelectorIsTrimmedAndBlankSelectorsAreDiscarded() {

        this.view.setMarkupSelector("  main-content \t");
        assertEquals("main-content", this.view.getMarkupSelector());

        this.view.setMarkupSelector("   ");
        assertNull(this.view.getMarkupSelector());

        this.view.setMarkupSelector("first");
        this.view.setMarkupSelector("second");
        assertEquals("second", this.view.getMarkupSelector());

        this.view.setMarkupSelector(null);
        assertNull(this.view.getMarkupSelector());
    }


    @Test
    void staticVariablesAreMergedAndExposedAsAnUnmodifiableMap() {

        this.view.addStaticVariable("first", "one");
        this.view.addStaticVariable("second", Integer.valueOf(2));

        assertEquals("one", this.view.getStaticVariables().get("first"));
        assertEquals(Integer.valueOf(2), this.view.getStaticVariables().get("second"));
        assertThrows(UnsupportedOperationException.class,
                () -> this.view.getStaticVariables().put("third", "three"));
        assertThrows(UnsupportedOperationException.class, () -> this.view.getStaticVariables().clear());

        Map<String, Object> additional = new HashMap<>();
        additional.put("first", "replaced");
        additional.put("third", "three");
        this.view.setStaticVariables(additional);

        assertEquals("replaced", this.view.getStaticVariables().get("first"));
        assertEquals("three", this.view.getStaticVariables().get("third"));

        this.view.setStaticVariables(null);
        assertEquals("replaced", this.view.getStaticVariables().get("first"));
    }


    @Test
    void explicitDefaultCharsetAndMediaTypesAreTracked() {

        this.view.setDefaultCharset(StandardCharsets.ISO_8859_1);
        this.view.setSupportedMediaTypes(Collections.singletonList(MediaType.APPLICATION_XHTML_XML));

        assertTrue(this.view.isDefaultCharsetSet());
        assertTrue(this.view.isSupportedMediaTypesSet());
        assertEquals(StandardCharsets.ISO_8859_1, this.view.getDefaultCharset());
        assertEquals(Collections.singletonList(MediaType.APPLICATION_XHTML_XML),
                this.view.getSupportedMediaTypes());
    }


    @Test
    void renderFailsImmediatelyWhenTemplateEngineIsMissing() {

        ThymeleafReactiveView viewWithoutEngine = new ThymeleafReactiveView();
        viewWithoutEngine.setApplicationContext(this.applicationContext);
        viewWithoutEngine.setTemplateName(TEMPLATE_NAME);
        viewWithoutEngine.setLocale(VIEW_LOCALE);

        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class,
                () -> viewWithoutEngine.render(Collections.emptyMap(), MediaType.TEXT_HTML, this.exchange).block());
        assertEquals("Property 'thymeleafTemplateEngine' is required", exception.getMessage());
        verify(this.exchange, never()).getResponse();
    }


    @Test
    void renderFailsWhenTemplateNameIsMissing() {

        this.view.setTemplateName(null);

        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class,
                () -> this.view.render(Collections.emptyMap(), MediaType.TEXT_HTML, this.exchange).block());
        assertEquals("Property 'templateName' is required", exception.getMessage());
    }


    @Test
    void renderFailsWhenLocaleIsMissing() {

        this.view.setLocale(null);

        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class,
                () -> this.view.render(Collections.emptyMap(), MediaType.TEXT_HTML, this.exchange).block());
        assertEquals("Property 'locale' is required", exception.getMessage());
    }


    @Test
    void fullModeRendersWithMergedModelAndProcessesTheTemplate() {

        this.view.addStaticVariable("shared", "static");
        this.view.addStaticVariable("staticOnly", "static-value");

        Map<String, Object> pathVariables = new HashMap<>();
        pathVariables.put("shared", "path");
        pathVariables.put("pathOnly", "path-value");
        this.exchange.getAttributes().put(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE, pathVariables);

        Map<String, Object> model = new LinkedHashMap<>();
        model.put("shared", "model");
        model.put("modelOnly", "model-value");

        DataBuffer first = mock(DataBuffer.class);
        DataBuffer second = mock(DataBuffer.class);
        when(this.templateEngine.processStream(
                anyString(), nullable(Set.class), any(IContext.class), any(DataBufferFactory.class),
                any(MediaType.class), any(Charset.class), anyInt()))
                .thenReturn(Flux.just(first, second));

        this.view.render(model, HTML_UTF_16, this.exchange).block();

        IContext context = verifyProcessStream(
                TEMPLATE_NAME, null, HTML_UTF_16, StandardCharsets.UTF_16,
                ThymeleafReactiveView.DEFAULT_RESPONSE_CHUNK_SIZE_BYTES);

        assertEquals("model", context.getVariable("shared"));
        assertEquals("static-value", context.getVariable("staticOnly"));
        assertEquals("path-value", context.getVariable("pathOnly"));
        assertEquals("model-value", context.getVariable("modelOnly"));
        assertEquals(VIEW_LOCALE, context.getLocale());

        assertInstanceOf(RequestContext.class,
                context.getVariable(SpringContextVariableNames.SPRING_REQUEST_CONTEXT));
        assertInstanceOf(SpringWebFluxThymeleafRequestContext.class,
                context.getVariable(SpringContextVariableNames.THYMELEAF_REQUEST_CONTEXT));
        ThymeleafEvaluationContext evaluationContext = assertInstanceOf(ThymeleafEvaluationContext.class,
                context.getVariable(ThymeleafEvaluationContext.THYMELEAF_EVALUATION_CONTEXT_CONTEXT_VARIABLE_NAME));
        assertSame(this.applicationContext, evaluationContext.getApplicationContext());

        assertEquals(HTML_UTF_16, this.responseHeaders.getContentType());
        assertEquals(VIEW_LOCALE, this.responseHeaders.getContentLanguage());
        assertFalse(model.containsKey(SpringContextVariableNames.SPRING_REQUEST_CONTEXT));

        @SuppressWarnings("unchecked")
        ArgumentCaptor<Publisher<DataBuffer>> streamCaptor = ArgumentCaptor.forClass(Publisher.class);
        verify(this.response).writeWith(streamCaptor.capture());
        verify(this.response, never()).writeAndFlushWith(any());

        List<DataBuffer> written = Flux.from(streamCaptor.getValue()).collectList().block();
        assertNotNull(written);
        assertEquals(Arrays.asList(first, second), written);
    }


    @Test
    void defaultCharsetIsUsedWhenContentTypeHasNoCharset() {

        this.view.setDefaultCharset(StandardCharsets.ISO_8859_1);

        this.view.render(Collections.<String, Object>emptyMap(), MediaType.TEXT_HTML, this.exchange).block();

        verifyProcessStream(
                TEMPLATE_NAME, null, MediaType.TEXT_HTML, StandardCharsets.ISO_8859_1,
                ThymeleafReactiveView.DEFAULT_RESPONSE_CHUNK_SIZE_BYTES);
        assertEquals(MediaType.TEXT_HTML, this.responseHeaders.getContentType());
    }


    @Test
    void chunkedModeFlushesOneBufferAtATime() {

        this.view.setResponseMaxChunkSizeBytes(128);

        DataBuffer first = mock(DataBuffer.class);
        DataBuffer second = mock(DataBuffer.class);
        when(this.templateEngine.processStream(
                anyString(), nullable(Set.class), any(IContext.class), any(DataBufferFactory.class),
                any(MediaType.class), any(Charset.class), anyInt()))
                .thenReturn(Flux.just(first, second));

        this.view.render(Collections.<String, Object>emptyMap(), MediaType.TEXT_HTML, this.exchange).block();

        verifyProcessStream(TEMPLATE_NAME, null, MediaType.TEXT_HTML, StandardCharsets.UTF_8, 128);
        verify(this.response, never()).writeWith(any());

        List<List<DataBuffer>> chunks = captureFlushedChunks();
        assertEquals(2, chunks.size());
        assertEquals(Collections.singletonList(first), chunks.get(0));
        assertEquals(Collections.singletonList(second), chunks.get(1));
    }


    @Test
    void dataDrivenModeUsesFlushEvenWithDefaultChunkSize() {

        IReactiveDataDriverContextVariable dataDriver =
                new ReactiveDataDriverContextVariable(Flux.just("one", "two"));
        Map<String, Object> model = new LinkedHashMap<>();
        model.put("items", dataDriver);

        this.view.render(model, MediaType.TEXT_HTML, this.exchange).block();

        verifyProcessStream(
                TEMPLATE_NAME, null, MediaType.TEXT_HTML, StandardCharsets.UTF_8,
                ThymeleafReactiveView.DEFAULT_RESPONSE_CHUNK_SIZE_BYTES);
        verify(this.response, never()).writeWith(any());
        verify(this.response).writeAndFlushWith(any());
    }


    @Test
    void reactiveExecutionAttributesAreAddedToTheModelWithoutMutatingTheOriginalModel() {

        AtomicInteger supplierCalls = new AtomicInteger();
        AtomicInteger functionCalls = new AtomicInteger();
        AtomicReference<ServerWebExchange> functionExchange = new AtomicReference<>();

        Publisher<?> directPublisher = Mono.just("direct-value");
        Supplier<Publisher<?>> supplier = () -> {
            supplierCalls.incrementAndGet();
            return Mono.just("supplier-value");
        };
        Function<ServerWebExchange, Publisher<?>> function = suppliedExchange -> {
            functionCalls.incrementAndGet();
            functionExchange.set(suppliedExchange);
            return Mono.just("function-value");
        };

        this.executionAttributes.put(
                SpringReactiveModelAdditionsUtils.toReactiveModelAdditionName("direct"), directPublisher);
        this.executionAttributes.put(
                SpringReactiveModelAdditionsUtils.toReactiveModelAdditionName("supplied"), supplier);
        this.executionAttributes.put(
                SpringReactiveModelAdditionsUtils.toReactiveModelAdditionName("functional"), function);
        this.executionAttributes.put(
                SpringReactiveModelAdditionsUtils.toReactiveModelAdditionName("nullValue"), null);
        this.executionAttributes.put("ordinaryExecutionAttribute", Mono.just("ignored"));

        Map<String, Object> model = new LinkedHashMap<>();
        model.put("existing", "existing-value");

        this.view.render(model, MediaType.TEXT_HTML, this.exchange).block();

        IContext context = verifyProcessStream(
                TEMPLATE_NAME, null, MediaType.TEXT_HTML, StandardCharsets.UTF_8,
                ThymeleafReactiveView.DEFAULT_RESPONSE_CHUNK_SIZE_BYTES);

        assertEquals("existing-value", context.getVariable("existing"));
        assertEquals("direct-value", context.getVariable("direct"));
        assertEquals("supplier-value", context.getVariable("supplied"));
        assertEquals("function-value", context.getVariable("functional"));
        assertFalse(context.containsVariable("nullValue"));
        assertFalse(context.containsVariable("ordinaryExecutionAttribute"));
        assertEquals(1, supplierCalls.get());
        assertEquals(1, functionCalls.get());
        assertSame(this.exchange, functionExchange.get());

        assertFalse(model.containsKey("direct"));
        assertFalse(model.containsKey("supplied"));
        assertFalse(model.containsKey("functional"));
    }


    @Test
    void conversionServiceBeanIsUsedForTheEvaluationContext() {

        ConversionService conversionService = mock(ConversionService.class);
        when(this.applicationContext.containsBean("webFluxConversionService")).thenReturn(true);
        when(this.applicationContext.getBean("webFluxConversionService")).thenReturn(conversionService);

        this.view.render(Collections.<String, Object>emptyMap(), MediaType.TEXT_HTML, this.exchange).block();

        IContext context = verifyProcessStream(
                TEMPLATE_NAME, null, MediaType.TEXT_HTML, StandardCharsets.UTF_8,
                ThymeleafReactiveView.DEFAULT_RESPONSE_CHUNK_SIZE_BYTES);
        ThymeleafEvaluationContext evaluationContext = assertInstanceOf(ThymeleafEvaluationContext.class,
                context.getVariable(ThymeleafEvaluationContext.THYMELEAF_EVALUATION_CONTEXT_CONTEXT_VARIABLE_NAME));

        assertNotNull(evaluationContext.getTypeConverter());
    }


    @Test
    void templateFragmentAndNamedParametersAreResolved() {

        this.executionAttributes.put(
                StandardExpressions.STANDARD_EXPRESSION_PARSER_ATTRIBUTE_NAME,
                new StandardExpressionParser());
        this.view.setTemplateName("templates/home :: content (title='Hello')");

        this.view.render(Collections.<String, Object>emptyMap(), MediaType.TEXT_HTML, this.exchange).block();

        Set<String> expectedSelectors = Collections.singleton("content");
        IContext context = verifyProcessStream(
                "templates/home", expectedSelectors, MediaType.TEXT_HTML, StandardCharsets.UTF_8,
                ThymeleafReactiveView.DEFAULT_RESPONSE_CHUNK_SIZE_BYTES);
        assertEquals("Hello", context.getVariable("title"));
    }


    @Test
    void configuredMarkupSelectorIsPassedToTheTemplateEngine() {

        this.view.setMarkupSelector("  body > main  ");

        this.view.render(Collections.<String, Object>emptyMap(), MediaType.TEXT_HTML, this.exchange).block();

        verifyProcessStream(
                TEMPLATE_NAME, Collections.singleton("body > main"), MediaType.TEXT_HTML,
                StandardCharsets.UTF_8, ThymeleafReactiveView.DEFAULT_RESPONSE_CHUNK_SIZE_BYTES);
    }


    @Test
    void fragmentInTemplateNameConflictsWithConfiguredMarkupSelector() {

        this.executionAttributes.put(
                StandardExpressions.STANDARD_EXPRESSION_PARSER_ATTRIBUTE_NAME,
                new StandardExpressionParser());
        this.view.setTemplateName("templates/home :: content");
        this.view.setMarkupSelector("other");

        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class,
                () -> this.view.render(Collections.emptyMap(), MediaType.TEXT_HTML, this.exchange).block());
        assertTrue(exception.getMessage().contains("Only one fragment selection is allowed."));
        verify(this.response, never()).writeWith(any());
        verify(this.response, never()).writeAndFlushWith(any());
    }


    @Test
    void syntheticFragmentParametersAreRejected() {

        this.executionAttributes.put(
                StandardExpressions.STANDARD_EXPRESSION_PARSER_ATTRIBUTE_NAME,
                new StandardExpressionParser());
        this.view.setTemplateName("templates/home :: content ('Hello')");

        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class,
                () -> this.view.render(Collections.emptyMap(), MediaType.TEXT_HTML, this.exchange).block());
        assertEquals("Parameters in a view specification must be named (non-synthetic): " +
                        "'templates/home :: content ('Hello')'",
                exception.getMessage());
    }


    @Test
    void invalidFragmentExpressionProducesAnIllegalArgumentException() {

        IStandardExpressionParser parser = mock(IStandardExpressionParser.class);
        when(parser.parseExpression(any(IExpressionContext.class), anyString()))
                .thenThrow(new TemplateProcessingException("invalid fragment"));
        this.executionAttributes.put(
                StandardExpressions.STANDARD_EXPRESSION_PARSER_ATTRIBUTE_NAME, parser);
        this.view.setTemplateName("templates/home :: [");

        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class,
                () -> this.view.render(Collections.emptyMap(), MediaType.TEXT_HTML, this.exchange).block());
        assertEquals("Invalid template name specification: 'templates/home :: ['", exception.getMessage());
    }


    private IContext verifyProcessStream(
            final String expectedTemplateName, final Set<String> expectedMarkupSelectors,
            final MediaType expectedContentType, final Charset expectedCharset,
            final int expectedChunkSize) {

        ArgumentCaptor<IContext> contextCaptor = ArgumentCaptor.forClass(IContext.class);
        if (expectedMarkupSelectors == null) {
            verify(this.templateEngine).processStream(
                    eq(expectedTemplateName), isNull(), contextCaptor.capture(), same(this.bufferFactory),
                    eq(expectedContentType), eq(expectedCharset), eq(expectedChunkSize));
        } else {
            verify(this.templateEngine).processStream(
                    eq(expectedTemplateName), eq(expectedMarkupSelectors), contextCaptor.capture(),
                    same(this.bufferFactory), eq(expectedContentType), eq(expectedCharset), eq(expectedChunkSize));
        }
        return contextCaptor.getValue();
    }


    @SuppressWarnings("unchecked")
    private List<List<DataBuffer>> captureFlushedChunks() {

        ArgumentCaptor<Publisher<Publisher<DataBuffer>>> captor = ArgumentCaptor.forClass(Publisher.class);
        verify(this.response).writeAndFlushWith(captor.capture());
        List<List<DataBuffer>> chunks = Flux.from(captor.getValue())
                .concatMap(chunk -> Flux.from(chunk).collectList())
                .collectList()
                .block();
        assertNotNull(chunks);
        return chunks;
    }

}
