    @Test
    void reactiveExecutionAttributesAreAddedToTheModelWithoutMutatingTheOriginalModel() {

        AtomicInteger supplierCalls = new AtomicInteger();
        AtomicInteger functionCalls = new AtomicInteger();
        AtomicReference<ServerWebExchange> functionExchange = new AtomicReference<>();

        Publisher<?> directPublisher = Mono.just("direct-value");
        Supplier<Publisher<?>> supplier = () -> {
            supplierCalls.incrementAndGet();
            return Mono.just("supplier-value");
        };
        Function<ServerWebExchange, Publisher<?>> function = suppliedExchange -> {
            functionCalls.incrementAndGet();
            functionExchange.set(suppliedExchange);
            return Mono.just("function-value");
        };

        this.executionAttributes.put(
                SpringReactiveModelAdditionsUtils.toReactiveModelAdditionName("direct"), directPublisher);
        this.executionAttributes.put(
                SpringReactiveModelAdditionsUtils.toReactiveModelAdditionName("supplied"), supplier);
        this.executionAttributes.put(
                SpringReactiveModelAdditionsUtils.toReactiveModelAdditionName("functional"), function);
        this.executionAttributes.put(
                SpringReactiveModelAdditionsUtils.toReactiveModelAdditionName("nullValue"), null);
        this.executionAttributes.put("ordinaryExecutionAttribute", Mono.just("ignored"));

        Map<String, Object> model = new LinkedHashMap<>();
        model.put("existing", "existing-value");

        this.view.render(model, MediaType.TEXT_HTML, this.exchange).block();

        IContext context = verifyProcessStream(
                TEMPLATE_NAME, null, MediaType.TEXT_HTML, StandardCharsets.UTF_8,
                ThymeleafReactiveView.DEFAULT_RESPONSE_CHUNK_SIZE_BYTES);

        assertEquals("existing-value", context.getVariable("existing"));
        assertEquals("direct-value", context.getVariable("direct"));
        assertEquals("supplier-value", context.getVariable("supplied"));
        assertEquals("function-value", context.getVariable("functional"));
        assertFalse(context.containsVariable("nullValue"));
        assertFalse(context.containsVariable("ordinaryExecutionAttribute"));
        assertEquals(1, supplierCalls.get());
        assertEquals(1, functionCalls.get());
        assertSame(this.exchange, functionExchange.get());

        assertFalse(model.containsKey("direct"));
        assertFalse(model.containsKey("supplied"));
        assertFalse(model.containsKey("functional"));
    }


