                .thenThrow(new TemplateProcessingException("invalid fragment"));
        this.executionAttributes.put(
                StandardExpressions.STANDARD_EXPRESSION_PARSER_ATTRIBUTE_NAME, parser);
        this.view.setTemplateName("templates/home :: [");

        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class,
                () -> this.view.render(Collections.emptyMap(), MediaType.TEXT_HTML, this.exchange).block());
        assertEquals("Invalid template name specification: 'templates/home :: ['", exception.getMessage());
    }


    private IContext verifyProcessStream(
            final String expectedTemplateName, final Set<String> expectedMarkupSelectors,
            final MediaType expectedContentType, final Charset expectedCharset,
            final int expectedChunkSize) {

        ArgumentCaptor<IContext> contextCaptor = ArgumentCaptor.forClass(IContext.class);
        if (expectedMarkupSelectors == null) {
            verify(this.templateEngine).processStream(
                    eq(expectedTemplateName), isNull(), contextCaptor.capture(), same(this.bufferFactory),
                    eq(expectedContentType), eq(expectedCharset), eq(expectedChunkSize));
        } else {
            verify(this.templateEngine).processStream(
                    eq(expectedTemplateName), eq(expectedMarkupSelectors), contextCaptor.capture(),
                    same(this.bufferFactory), eq(expectedContentType), eq(expectedCharset), eq(expectedChunkSize));
        }
        return contextCaptor.getValue();
    }


    @SuppressWarnings("unchecked")
    private List<List<DataBuffer>> captureFlushedChunks() {

        ArgumentCaptor<Publisher<Publisher<DataBuffer>>> captor = ArgumentCaptor.forClass(Publisher.class);
        verify(this.response).writeAndFlushWith(captor.capture());
        List<List<DataBuffer>> chunks = Flux.from(captor.getValue())
                .concatMap(chunk -> Flux.from(chunk).collectList())
                .collectList()
                .block();
        assertNotNull(chunks);
        return chunks;
    }

