    @Test
    void fullModeRendersWithMergedModelAndProcessesTheTemplate() {

        this.view.addStaticVariable("shared", "static");
        this.view.addStaticVariable("staticOnly", "static-value");

        Map<String, Object> pathVariables = new HashMap<>();
        pathVariables.put("shared", "path");
        pathVariables.put("pathOnly", "path-value");
        this.exchange.getAttributes().put(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE, pathVariables);

        Map<String, Object> model = new LinkedHashMap<>();
        model.put("shared", "model");
        model.put("modelOnly", "model-value");

        DataBuffer first = mock(DataBuffer.class);
        DataBuffer second = mock(DataBuffer.class);
        when(this.templateEngine.processStream(
                anyString(), nullable(Set.class), any(IContext.class), any(DataBufferFactory.class),
                any(MediaType.class), any(Charset.class), anyInt()))
                .thenReturn(Flux.just(first, second));

        this.view.render(model, HTML_UTF_16, this.exchange).block();

        IContext context = verifyProcessStream(
                TEMPLATE_NAME, null, HTML_UTF_16, StandardCharsets.UTF_16,
                ThymeleafReactiveView.DEFAULT_RESPONSE_CHUNK_SIZE_BYTES);

        assertEquals("model", context.getVariable("shared"));
        assertEquals("static-value", context.getVariable("staticOnly"));
        assertEquals("path-value", context.getVariable("pathOnly"));
        assertEquals("model-value", context.getVariable("modelOnly"));
        assertEquals(VIEW_LOCALE, context.getLocale());

        assertInstanceOf(RequestContext.class,
                context.getVariable(SpringContextVariableNames.SPRING_REQUEST_CONTEXT));
        assertInstanceOf(SpringWebFluxThymeleafRequestContext.class,
                context.getVariable(SpringContextVariableNames.THYMELEAF_REQUEST_CONTEXT));
        ThymeleafEvaluationContext evaluationContext = assertInstanceOf(ThymeleafEvaluationContext.class,
                context.getVariable(ThymeleafEvaluationContext.THYMELEAF_EVALUATION_CONTEXT_CONTEXT_VARIABLE_NAME));
        assertSame(this.applicationContext, evaluationContext.getApplicationContext());

        assertEquals(HTML_UTF_16, this.responseHeaders.getContentType());
        assertEquals(VIEW_LOCALE, this.responseHeaders.getContentLanguage());
        assertFalse(model.containsKey(SpringContextVariableNames.SPRING_REQUEST_CONTEXT));

        @SuppressWarnings("unchecked")
        ArgumentCaptor<Publisher<DataBuffer>> streamCaptor = ArgumentCaptor.forClass(Publisher.class);
        verify(this.response).writeWith(streamCaptor.capture());
        verify(this.response, never()).writeAndFlushWith(any());

        List<DataBuffer> written = Flux.from(streamCaptor.getValue()).collectList().block();
        assertNotNull(written);
        assertEquals(Arrays.asList(first, second), written);
    }


