    void fragmentInTemplateNameConflictsWithConfiguredMarkupSelector() {

        this.executionAttributes.put(
                StandardExpressions.STANDARD_EXPRESSION_PARSER_ATTRIBUTE_NAME,
                new StandardExpressionParser());
        this.view.setTemplateName("templates/home :: content");
        this.view.setMarkupSelector("other");

        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class,
                () -> this.view.render(Collections.emptyMap(), MediaType.TEXT_HTML, this.exchange).block());
