    private static final class ExecutionAttributesDialect implements IDialect {

        private final String name;
        private final Object value;

        private ExecutionAttributesDialect(final String name, final Object value) {
            this.name = name;
            this.value = value;
        }

        @Override
        public String getName() {
            return "execution-attributes-dialect";
        }

        @Override
        public Map<String, Object> getExecutionAttributes() {
            final Map<String, Object> attributes = new HashMap<String, Object>(2, 1.0f);
            attributes.put(this.name, this.value);
            return attributes;
        }
    }




    private static final class RecordedExecution {

        private final String templateName;
        private final Set<String> markupSelectors;
        private final IContext context;
        private final MediaType mediaType;
        private final Charset charset;
        private final int responseMaxChunkSizeBytes;

        private RecordedExecution(final String templateName, final Set<String> markupSelectors,
                                  final IContext context, final MediaType mediaType, final Charset charset,
                                  final int responseMaxChunkSizeBytes) {
            this.templateName = templateName;
            this.markupSelectors = markupSelectors;
            this.context = context;
            this.mediaType = mediaType;
            this.charset = charset;
            this.responseMaxChunkSizeBytes = responseMaxChunkSizeBytes;
        }
    }




    private static final class RecordingTemplateEngine extends SpringWebFluxTemplateEngine {

        private final List<String> outputBufferContents = new ArrayList<String>();
        private final List<RecordedExecution> executions = new ArrayList<RecordedExecution>();
        private final Set<IDialect> additionalDialects = new LinkedHashSet<IDialect>();

        private RecordingTemplateEngine() {
            final StringTemplateResolver templateResolver = new StringTemplateResolver();
            templateResolver.setCacheable(false);
            setTemplateResolver(templateResolver);
        }

        private void setOutputBufferContents(final String... contents) {
            this.outputBufferContents.clear();
            this.outputBufferContents.addAll(Arrays.asList(contents));
        }

        private void addDialect(final IDialect dialect) {
            this.additionalDialects.add(dialect);
            setAdditionalDialects(this.additionalDialects);
        }

        private RecordedExecution lastExecution() {
            assertFalse(this.executions.isEmpty(), "The template engine was not executed");
            return this.executions.get(this.executions.size() - 1);
        }

        @Override
        public Publisher<DataBuffer> processStream(
                final String template, final Set<String> markupSelectors, final IContext context,
                final DataBufferFactory bufferFactory, final MediaType mediaType, final Charset charset,
                final int responseMaxChunkSizeBytes) {

            this.executions.add(new RecordedExecution(
                    template, markupSelectors, context, mediaType, charset, responseMaxChunkSizeBytes));

            final List<String> contents =
                    (this.outputBufferContents.isEmpty() ?
                            Collections.singletonList("rendered") : this.outputBufferContents);

            return Flux.fromIterable(contents)
                    .map(content -> bufferFactory.wrap(content.getBytes(charset)));
        }
    }




    private static final class RecordingServerHttpResponse extends AbstractServerHttpResponse {

        private final List<String> buffers = new ArrayList<String>();
        private final List<List<String>> flushGroups = new ArrayList<List<String>>();
        private int writeWithInvocations = 0;
        private int writeAndFlushWithInvocations = 0;

        private RecordingServerHttpResponse() {
            super(DefaultDataBufferFactory.sharedInstance);
        }

        @Override
        @SuppressWarnings("unchecked")
        public <T> T getNativeResponse() {
            return null;
        }

        @Override
        protected Mono<Void> writeWithInternal(final Publisher<? extends DataBuffer> body) {
            this.writeWithInvocations++;
            return Flux.from(body)
                    .doOnNext(buffer -> this.buffers.add(readBuffer(buffer)))
                    .then();
        }

        @Override
        protected Mono<Void> writeAndFlushWithInternal(
                final Publisher<? extends Publisher<? extends DataBuffer>> body) {
            this.writeAndFlushWithInvocations++;
            return Flux.from(body)
                    .concatMap(inner -> Flux.from(inner)
                            .map(this::readBuffer)
                            .collectList()
                            .doOnNext(group -> {
                                this.flushGroups.add(group);
                                this.buffers.addAll(group);
                            })
                            .then())
                    .then();
        }

        @Override
        protected void applyStatusCode() {
            // Nothing to do
        }

        @Override
        protected void applyHeaders() {
            // Nothing to do
        }

        @Override
        protected void applyCookies() {
            // Nothing to do
        }

        private String body() {
            final StringBuilder body = new StringBuilder();
            for (final String buffer : this.buffers) {
                body.append(buffer);
            }
            return body.toString();
        }

        private String readBuffer(final DataBuffer buffer) {
            final byte[] bytes = new byte[buffer.readableByteCount()];
            buffer.read(bytes);
            return new String(bytes, StandardCharsets.UTF_8);
        }
    }

