@Test
public void fullModeWritesStreamWithWriteWith() {

    this.templateEngine.setOutputBufferContents("Hello", " World");

    render(new HashMap<String, Object>(), HTML);

    final RecordedExecution execution = this.templateEngine.lastExecution();
    assertEquals(TEMPLATE_NAME, execution.templateName);
    assertNull(execution.markupSelectors);
    assertEquals(ThymeleafReactiveView.DEFAULT_RESPONSE_CHUNK_SIZE_BYTES, execution.responseMaxChunkSizeBytes);
    assertEquals(HTML, execution.mediaType);
    assertEquals(StandardCharsets.UTF_8, execution.charset);

    assertEquals(1, this.response.writeWithInvocations);
    assertEquals(0, this.response.writeAndFlushWithInvocations);
    assertEquals("Hello World", this.response.body());
    assertEquals(HTML, this.response.getHeaders().getContentType());
}


