   149	                    standardDialectPrefix = dialectPrefix;
   150	                }
   151	
   152	                final Set<IProcessor> dialectProcessors = processorDialect.getProcessors(dialectPrefix);
   153	                if (dialectProcessors == null) {
   154	                    throw new ConfigurationException("Dialect should not return null processor set: " + dialect.getClass().getName());
   155	                }
   156	
   157	                for (final IProcessor dialectProcessor : dialectProcessors) {
   158	
   159	                    if (dialectProcessor == null) {
   160	                        throw new ConfigurationException("Dialect should not return null processor in processor set: " + dialect.getClass().getName());
   161	                    }
   162	
   163	                    // Obtain and check template mode
   164	                    final TemplateMode templateMode = dialectProcessor.getTemplateMode();
   165	                    if (templateMode == null) {
   166	                        throw new ConfigurationException("Template mode cannot be null (processor: " + dialectProcessor.getClass().getName() + ")");
   167	                    }
   168	
   169	                    if (dialectProcessor instanceof IElementProcessor) { // can be either a tag processor or a node one
   170	
   171	                        List<IElementProcessor> processorsForTemplateMode = elementProcessorListsByTemplateMode.get(templateMode);
   172	                        if (processorsForTemplateMode == null) {
   173	                            processorsForTemplateMode = new ArrayList<IElementProcessor>(5);
   174	                            elementProcessorListsByTemplateMode.put(templateMode, processorsForTemplateMode);
   175	                        }
   176	                        processorsForTemplateMode.add(ProcessorConfigurationUtils.wrap((IElementProcessor)dialectProcessor, processorDialect));
   177	                        Collections.sort(processorsForTemplateMode, ProcessorComparators.PROCESSOR_COMPARATOR);
   178	
   179	
   180	                    } else if (dialectProcessor instanceof ITemplateBoundariesProcessor) {
   181	
   182	                        List<ITemplateBoundariesProcessor> processorsForTemplateMode = templateBoundariesProcessorListsByTemplateMode.get(templateMode);
   183	                        if (processorsForTemplateMode == null) {
   184	                            processorsForTemplateMode = new ArrayList<ITemplateBoundariesProcessor>(5);
   185	                            templateBoundariesProcessorListsByTemplateMode.put(templateMode, processorsForTemplateMode);
   186	                        }
   187	                        processorsForTemplateMode.add(ProcessorConfigurationUtils.wrap((ITemplateBoundariesProcessor)dialectProcessor, processorDialect));
   188	                        Collections.sort(processorsForTemplateMode, ProcessorComparators.PROCESSOR_COMPARATOR);
   189	
   190	                    } else if (dialectProcessor instanceof ICDATASectionProcessor) {
   191	
   192	                        List<ICDATASectionProcessor> processorsForTemplateMode = cdataSectionProcessorListsByTemplateMode.get(templateMode);
   193	                        if (processorsForTemplateMode == null) {
   194	                            processorsForTemplateMode = new ArrayList<ICDATASectionProcessor>(5);
   195	                            cdataSectionProcessorListsByTemplateMode.put(templateMode, processorsForTemplateMode);
   196	                        }
   197	                        processorsForTemplateMode.add(ProcessorConfigurationUtils.wrap((ICDATASectionProcessor)dialectProcessor, processorDialect));
   198	                        Collections.sort(processorsForTemplateMode, ProcessorComparators.PROCESSOR_COMPARATOR);
   199	
   200	                    } else if (dialectProcessor instanceof ICommentProcessor) {
   201	
   202	                        List<ICommentProcessor> processorsForTemplateMode = commentProcessorListsByTemplateMode.get(templateMode);
   203	                        if (processorsForTemplateMode == null) {
   204	                            processorsForTemplateMode = new ArrayList<ICommentProcessor>(5);
   205	                            commentProcessorListsByTemplateMode.put(templateMode, processorsForTemplateMode);

206	                        }
207	                        processorsForTemplateMode.add(ProcessorConfigurationUtils.wrap((ICommentProcessor)dialectProcessor, processorDialect));
208	                        Collections.sort(processorsForTemplateMode, ProcessorComparators.PROCESSOR_COMPARATOR);
209	
210	                    } else if (dialectProcessor instanceof IDocTypeProcessor) {
211	
212	                        List<IDocTypeProcessor> processorsForTemplateMode = docTypeProcessorListsByTemplateMode.get(templateMode);
213	                        if (processorsForTemplateMode == null) {
214	                            processorsForTemplateMode = new ArrayList<IDocTypeProcessor>(5);
215	                            docTypeProcessorListsByTemplateMode.put(templateMode, processorsForTemplateMode);
216	                        }
217	                        processorsForTemplateMode.add(ProcessorConfigurationUtils.wrap((IDocTypeProcessor)dialectProcessor, processorDialect));
218	                        Collections.sort(processorsForTemplateMode, ProcessorComparators.PROCESSOR_COMPARATOR);
219	
220	                    } else if (dialectProcessor instanceof IProcessingInstructionProcessor) {
221	
222	                        List<IProcessingInstructionProcessor> processorsForTemplateMode = processingInstructionProcessorListsByTemplateMode.get(templateMode);
223	                        if (processorsForTemplateMode == null) {
224	                            processorsForTemplateMode = new ArrayList<IProcessingInstructionProcessor>(5);
225	                            processingInstructionProcessorListsByTemplateMode.put(templateMode, processorsForTemplateMode);
226	                        }
227	                        processorsForTemplateMode.add(ProcessorConfigurationUtils.wrap((IProcessingInstructionProcessor)dialectProcessor, processorDialect));
228	                        Collections.sort(processorsForTemplateMode, ProcessorComparators.PROCESSOR_COMPARATOR);
229	
230	                    } else if (dialectProcessor instanceof ITextProcessor) {
231	
232	                        List<ITextProcessor> processorsForTemplateMode = textProcessorListsByTemplateMode.get(templateMode);
233	                        if (processorsForTemplateMode == null) {
234	                            processorsForTemplateMode = new ArrayList<ITextProcessor>(5);
235	                            textProcessorListsByTemplateMode.put(templateMode, processorsForTemplateMode);
236	                        }
237	                        processorsForTemplateMode.add(ProcessorConfigurationUtils.wrap((ITextProcessor)dialectProcessor, processorDialect));
238	                        Collections.sort(processorsForTemplateMode, ProcessorComparators.PROCESSOR_COMPARATOR);
239	
240	                    } else if (dialectProcessor instanceof IXMLDeclarationProcessor) {
241	
242	                        List<IXMLDeclarationProcessor> processorsForTemplateMode = xmlDeclarationProcessorListsByTemplateMode.get(templateMode);
243	                        if (processorsForTemplateMode == null) {
244	                            processorsForTemplateMode = new ArrayList<IXMLDeclarationProcessor>(5);
245	                            xmlDeclarationProcessorListsByTemplateMode.put(templateMode, processorsForTemplateMode);
246	                        }
247	                        processorsForTemplateMode.add(ProcessorConfigurationUtils.wrap((IXMLDeclarationProcessor)dialectProcessor, processorDialect));
248	                        Collections.sort(processorsForTemplateMode, ProcessorComparators.PROCESSOR_COMPARATOR);
249	
250	                    }
251	
252	
253	                }
254	
255	            }
256	
257	
258	            /*
259	             * STEP TWO for each dialect: merge execution attributes
260	             */
261	            if (dialect instanceof IExecutionAttributeDialect) {
262	
263	                final Map<String, Object> dialectExecutionAttributes = ((IExecutionAttributeDialect) dialect).getExecutionAttributes();
264	                if (dialectExecutionAttributes != null) {
265	                    for (final Map.Entry<String, Object> entry : dialectExecutionAttributes.entrySet()) {
266	                        final String executionAttributeName = entry.getKey();
267	                        if (executionAttributes.containsKey(executionAttributeName)) {
268	                            throw new ConfigurationException(
269	                                    "Conflicting execution attribute. Two or more dialects specify an execution " +
270	                                    "attribute with the same name \"" + executionAttributeName + "\".");
271	                        }
272	                        executionAttributes.put(entry.getKey(), entry.getValue());
273	                    }
274	                }
275	
276	            }
277	
278	
279	            /*
280	             * STEP THREE for each dialect: aggregate all the expression object factories
281	             */
282	            if (dialect instanceof IExpressionObjectDialect) {
283	
284	                final IExpressionObjectFactory factory = ((IExpressionObjectDialect) dialect).getExpressionObjectFactory();
285	                if (factory != null) {
286	                    aggregateExpressionObjectFactory.add(factory);
287	                }
288	
289	            }
290	
291	
292	            /*
293	             * STEP FOUR for each dialect: aggregate pre-processors (and check the correctness of the list)
294	             */
295	            if (dialect instanceof IPreProcessorDialect) {
296	
297	                final Set<IPreProcessor> dialectPreProcessors = ((IPreProcessorDialect)dialect).getPreProcessors();
298	                if (dialectPreProcessors != null) {
299	
300	                    for (final IPreProcessor preProcessor : dialectPreProcessors) {
301	
302	                        if (preProcessor == null) {
303	                            throw new ConfigurationException(
304	                                    "Pre-Processor list for dialect " + dialect.getClass().getName() + " includes a " +
305	                                    "null entry, which is forbidden.");
306	                        }

307	
308	                        // Obtain and check template mode
309	                        final TemplateMode templateMode = preProcessor.getTemplateMode();
310	                        if (templateMode == null) {
311	                            throw new ConfigurationException(
312	                                    "Template mode cannot be null (pre-processor: " + preProcessor.getClass().getName() +
313	                                    ", dialect" + dialect.getClass().getName() + ")");
314	                        }
315	
316	                        // Check the handler class: should extend ITemplateHandler and have an empty constructor
317	                        final Class<?> handlerClass = preProcessor.getHandlerClass();
318	                        if (handlerClass == null) {
319	                            throw new ConfigurationException(
320	                                    "Pre-Processor " + preProcessor.getClass().getName() + " for dialect " +
321	                                    preProcessor.getClass().getName() + " returns a null handler class, which is forbidden.");
322	                        }
323	                        if (!ITemplateHandler.class.isAssignableFrom(handlerClass)) {
324	                            throw new ConfigurationException(
325	                                    "Handler class " + handlerClass.getName() + " specified for " +
326	                                    "pre-processor " + preProcessor.getClass().getName() + " in dialect " +
327	                                    dialect.getClass().getName() + " does not implement required " +
328	                                    "interface " + ITemplateHandler.class.getName());
329	                        }
330	                        try {
331	                            // Check the empty constructor is present -- we will need to use it for creating new instances
332	                            handlerClass.getConstructor(new Class[0]);
333	                        } catch (final NoSuchMethodException e) {
334	                            throw new ConfigurationException(
335	                                    "Pre-Processor class " + handlerClass.getName() + " specified for " +
336	                                    "pre-processor " + preProcessor.getClass().getName() + " in dialect " +
337	                                    dialect.getClass().getName() + " does not implement required " +
338	                                    "zero-argument constructor.", e);
339	                        }
340	
341	                        // Add the pre-processor to its corresponding map and sort
342	                        List<IPreProcessor> preProcessorsForTemplateMode = preProcessorListsByTemplateMode.get(templateMode);
343	                        if (preProcessorsForTemplateMode == null) {
344	                            preProcessorsForTemplateMode = new ArrayList<IPreProcessor>(5);
345	                            preProcessorListsByTemplateMode.put(templateMode, preProcessorsForTemplateMode);
346	                        }
347	                        preProcessorsForTemplateMode.add(preProcessor);
348	                        Collections.sort(preProcessorsForTemplateMode, ProcessorComparators.PRE_PROCESSOR_COMPARATOR);
349	
350	                    }
351	
352	                }
353	
354	            }
355	
356	
357	            /*
358	             * STEP FIVE for each dialect: aggregate post-processors (and check the correctness of the list)
359	             */
360	            if (dialect instanceof IPostProcessorDialect) {
361	
362	                final Set<IPostProcessor> dialectPostProcessors = ((IPostProcessorDialect)dialect).getPostProcessors();
363	                if (dialectPostProcessors != null) {
364	
365	                    for (final IPostProcessor postProcessor : dialectPostProcessors) {
366	
367	                        if (postProcessor == null) {
368	                            throw new ConfigurationException(
369	                                    "Post-Processor list for dialect " + dialect.getClass().getName() + " includes a " +
370	                                    "null entry, which is forbidden.");
371	                        }
372	
373	                        // Obtain and check template mode
374	                        final TemplateMode templateMode = postProcessor.getTemplateMode();
375	                        if (templateMode == null) {
376	                            throw new ConfigurationException(
377	                                    "Template mode cannot be null (post-processor: " + postProcessor.getClass().getName() +
378	                                    ", dialect" + dialect.getClass().getName() + ")");
379	                        }
380	
381	                        // Check the handler class: should extend ITemplateHandler and have an empty constructor
382	                        final Class<?> handlerClass = postProcessor.getHandlerClass();
383	                        if (handlerClass == null) {
384	                            throw new ConfigurationException(
385	                                    "Post-Processor " + postProcessor.getClass().getName() + " for dialect " +
386	                                    postProcessor.getClass().getName() + " returns a null handler class, which is forbidden.");
387	                        }
388	                        if (!ITemplateHandler.class.isAssignableFrom(handlerClass)) {
389	                            throw new ConfigurationException(
390	                                    "Handler class " + handlerClass.getName() + " specified for " +
391	                                    "post-processor " + postProcessor.getClass().getName() + " in dialect " +
392	                                    dialect.getClass().getName() + " does not implement required " +
393	                                    "interface " + ITemplateHandler.class.getName());
394	                        }
395	                        try {
396	                            // Check the empty constructor is present -- we will need to use it for creating new instances
397	                            handlerClass.getConstructor(new Class[0]);
398	                        } catch (final NoSuchMethodException e) {
399	                            throw new ConfigurationException(
400	                                    "Post-Processor class " + handlerClass.getName() + " specified for " +
401	                                    "post-processor " + postProcessor.getClass().getName() + " in dialect " +
402	                                    dialect.getClass().getName() + " does not implement required " +
403	                                    "zero-argument constructor.", e);
404	                        }
405	
406	                        // Add the pre-processor to its corresponding map and sort
407	                        List<IPostProcessor> postProcessorsForTemplateMode = postProcessorListsByTemplateMode.get(templateMode);

408	                        if (postProcessorsForTemplateMode == null) {
409	                            postProcessorsForTemplateMode = new ArrayList<IPostProcessor>(5);
410	                            postProcessorListsByTemplateMode.put(templateMode, postProcessorsForTemplateMode);
411	                        }
412	                        postProcessorsForTemplateMode.add(postProcessor);
413	                        Collections.sort(postProcessorsForTemplateMode, ProcessorComparators.POST_PROCESSOR_COMPARATOR);
414	
415	                    }
416	
417	                }
418	
419	            }
420	
421	
422	            /*
423	             * LAST STEP for each dialect: add it to the dialects set
424	             */
425	            dialects.add(dialect);
426	
427	
428	        }
429	
430	
431	        // Time to turn the list-based structures into sets -- we needed the lists because we needed a way to order them using Collections.sort()
432	        final EnumMap<TemplateMode, Set<ITemplateBoundariesProcessor>> templateBoundariesProcessorsByTemplateMode = listMapToSetMap(templateBoundariesProcessorListsByTemplateMode);
433	        final EnumMap<TemplateMode, Set<ICDATASectionProcessor>> cdataSectionProcessorsByTemplateMode = listMapToSetMap(cdataSectionProcessorListsByTemplateMode);
434	        final EnumMap<TemplateMode, Set<ICommentProcessor>> commentProcessorsByTemplateMode = listMapToSetMap(commentProcessorListsByTemplateMode);
435	        final EnumMap<TemplateMode, Set<IDocTypeProcessor>> docTypeProcessorsByTemplateMode = listMapToSetMap(docTypeProcessorListsByTemplateMode);
436	        final EnumMap<TemplateMode, Set<IElementProcessor>> elementProcessorsByTemplateMode = listMapToSetMap(elementProcessorListsByTemplateMode);
437	        final EnumMap<TemplateMode, Set<IProcessingInstructionProcessor>> processingInstructionProcessorsByTemplateMode = listMapToSetMap(processingInstructionProcessorListsByTemplateMode);
438	        final EnumMap<TemplateMode, Set<ITextProcessor>> textProcessorsByTemplateMode = listMapToSetMap(textProcessorListsByTemplateMode);
439	        final EnumMap<TemplateMode, Set<IXMLDeclarationProcessor>> xmlDeclarationProcessorsByTemplateMode = listMapToSetMap(xmlDeclarationProcessorListsByTemplateMode);
440	        final EnumMap<TemplateMode, Set<IPreProcessor>> preProcessorsByTemplateMode = listMapToSetMap(preProcessorListsByTemplateMode);
441	        final EnumMap<TemplateMode, Set<IPostProcessor>> postProcessorsByTemplateMode = listMapToSetMap(postProcessorListsByTemplateMode);
442	
443	
444	        // Initialize the ElementDefinitions and AttributeDefinitions structures -- they need the element processors so that these
445	        // are directly applied to the element/attribute definitions and therefore per element/attribute matching is not required
446	        // during template processing.
447	        final ElementDefinitions elementDefinitions = new ElementDefinitions(elementProcessorsByTemplateMode);
448	        final AttributeDefinitions attributeDefinitions = new AttributeDefinitions(elementProcessorsByTemplateMode);
449	
450	
451	        // Traverse the sets of processors in order to set the AttributeDefinitions and/or ElementDefinitions objects
452	        // to those that need them in order to initialize and cache attribute/element definition-related structures
453	        initializeDefinitionsForProcessors(templateBoundariesProcessorsByTemplateMode, elementDefinitions, attributeDefinitions);
454	        initializeDefinitionsForProcessors(cdataSectionProcessorsByTemplateMode, elementDefinitions, attributeDefinitions);
455	        initializeDefinitionsForProcessors(commentProcessorsByTemplateMode, elementDefinitions, attributeDefinitions);
456	        initializeDefinitionsForProcessors(docTypeProcessorsByTemplateMode, elementDefinitions, attributeDefinitions);
457	        initializeDefinitionsForProcessors(elementProcessorsByTemplateMode, elementDefinitions, attributeDefinitions);
458	        initializeDefinitionsForProcessors(processingInstructionProcessorsByTemplateMode, elementDefinitions, attributeDefinitions);
459	        initializeDefinitionsForProcessors(textProcessorsByTemplateMode, elementDefinitions, attributeDefinitions);
460	        initializeDefinitionsForProcessors(xmlDeclarationProcessorsByTemplateMode, elementDefinitions, attributeDefinitions);
461	        initializeDefinitionsForPreProcessors(preProcessorsByTemplateMode, elementDefinitions, attributeDefinitions);
462	        initializeDefinitionsForPostProcessors(postProcessorsByTemplateMode, elementDefinitions, attributeDefinitions);
463	
464	
465	        return new DialectSetConfiguration(
466	                new LinkedHashSet<DialectConfiguration>(dialectConfigurations), dialects,
467	                standardDialectPresent, standardDialectPrefix,
468	                executionAttributes, aggregateExpressionObjectFactory,
469	                elementDefinitions, attributeDefinitions,
470	                templateBoundariesProcessorsByTemplateMode,
471	                cdataSectionProcessorsByTemplateMode, commentProcessorsByTemplateMode, docTypeProcessorsByTemplateMode,
472	                elementProcessorsByTemplateMode, processingInstructionProcessorsByTemplateMode,
473	                textProcessorsByTemplateMode, xmlDeclarationProcessorsByTemplateMode,
474	                preProcessorsByTemplateMode, postProcessorsByTemplateMode);
475	
476	    }
