480	    private static <T> EnumMap<TemplateMode, Set<T>> listMapToSetMap(final EnumMap<TemplateMode, List<T>> map) {
481	        final EnumMap<TemplateMode, Set<T>> newMap = new EnumMap<TemplateMode, Set<T>>(TemplateMode.class);
482	        for (final Map.Entry<TemplateMode, List<T>> entry : map.entrySet()) {
483	            newMap.put(entry.getKey(), new LinkedHashSet<T>(entry.getValue()));
484	        }
485	        return newMap;
486	    }
