491	    private static void initializeDefinitionsForProcessors(
492	            final EnumMap<TemplateMode, ? extends Set<? extends IProcessor>> processorsByTemplateMode,
493	            final ElementDefinitions elementDefinitions, final AttributeDefinitions attributeDefinitions) {
494	
495	        for (final Map.Entry<TemplateMode, ? extends Set<? extends IProcessor>> entry : processorsByTemplateMode.entrySet()) {
496	            final Set<? extends IProcessor> processors = entry.getValue();
497	            for (final IProcessor processor : processors) {
498	                if (processor instanceof IElementDefinitionsAware) {
499	                    ((IElementDefinitionsAware) processor).setElementDefinitions(elementDefinitions);
500	                }
501	                if (processor instanceof IAttributeDefinitionsAware) {
502	                    ((IAttributeDefinitionsAware) processor).setAttributeDefinitions(attributeDefinitions);
503	                }
504	            }
505	        }
506	
507	    }
