510	    private static void initializeDefinitionsForPreProcessors(
511	            final EnumMap<TemplateMode, ? extends Set<IPreProcessor>> preProcessorsByTemplateMode,
512	            final ElementDefinitions elementDefinitions, final AttributeDefinitions attributeDefinitions) {
513	
514	        for (final Map.Entry<TemplateMode, ? extends Set<IPreProcessor>> entry : preProcessorsByTemplateMode.entrySet()) {
515	            final Set<IPreProcessor> preProcessors = entry.getValue();
516	            for (final IPreProcessor preProcessor : preProcessors) {
517	                if (preProcessor instanceof IElementDefinitionsAware) {
518	                    ((IElementDefinitionsAware) preProcessor).setElementDefinitions(elementDefinitions);
519	                }
520	                if (preProcessor instanceof IAttributeDefinitionsAware) {

520	                if (preProcessor instanceof IAttributeDefinitionsAware) {
521	                    ((IAttributeDefinitionsAware) preProcessor).setAttributeDefinitions(attributeDefinitions);
522	                }
523	            }
524	        }
525	
526	    }
