529	    private static void initializeDefinitionsForPostProcessors(
530	            final EnumMap<TemplateMode, ? extends Set<IPostProcessor>> postProcessorsByTemplateMode,
531	            final ElementDefinitions elementDefinitions, final AttributeDefinitions attributeDefinitions) {
532	
533	        for (final Map.Entry<TemplateMode, ? extends Set<IPostProcessor>> entry : postProcessorsByTemplateMode.entrySet()) {
534	            final Set<IPostProcessor> postProcessors = entry.getValue();
535	            for (final IPostProcessor postProcessor : postProcessors) {
536	                if (postProcessor instanceof IElementDefinitionsAware) {
537	                    ((IElementDefinitionsAware) postProcessor).setElementDefinitions(elementDefinitions);
538	                }
539	                if (postProcessor instanceof IAttributeDefinitionsAware) {
540	                    ((IAttributeDefinitionsAware) postProcessor).setAttributeDefinitions(attributeDefinitions);
541	                }
542	            }
543	        }
544	
545	    }
