    @Test
    void buildRequiresNonNullDialectConfigurationSet() {

        final IllegalArgumentException exception =
                assertThrows(IllegalArgumentException.class, () -> DialectSetConfiguration.build(null));

        assertEquals("Dialect configuration set cannot be null", exception.getMessage());
    }


    @Test
    void emptyInputProducesEmptyConfiguration() {

        final DialectSetConfiguration configuration = DialectSetConfiguration.build(dialectConfigurations());

        assertTrue(configuration.getDialectConfigurations().isEmpty());
        assertTrue(configuration.getDialects().isEmpty());
        assertFalse(configuration.isStandardDialectPresent());
        assertNull(configuration.getStandardDialectPrefix());
        assertTrue(configuration.getExecutionAttributes().isEmpty());
        assertFalse(configuration.hasExecutionAttribute("anything"));
        assertNull(configuration.getExecutionAttribute("anything"));

        assertNotNull(configuration.getElementDefinitions());
        assertNotNull(configuration.getAttributeDefinitions());
        assertNotNull(configuration.getExpressionObjectFactory());

        final IExpressionObjectFactory expressionObjectFactory = configuration.getExpressionObjectFactory();
        assertNull(expressionObjectFactory.getAllExpressionObjectNames());
        assertNull(expressionObjectFactory.buildObject(null, "anything"));
        assertFalse(expressionObjectFactory.isCacheable("anything"));

        assertTrue(configuration.getTemplateBoundariesProcessors(TemplateMode.HTML).isEmpty());
        assertTrue(configuration.getCDATASectionProcessors(TemplateMode.HTML).isEmpty());
        assertTrue(configuration.getCommentProcessors(TemplateMode.HTML).isEmpty());
        assertTrue(configuration.getDocTypeProcessors(TemplateMode.HTML).isEmpty());
        assertTrue(configuration.getElementProcessors(TemplateMode.HTML).isEmpty());
        assertTrue(configuration.getProcessingInstructionProcessors(TemplateMode.HTML).isEmpty());
        assertTrue(configuration.getTextProcessors(TemplateMode.HTML).isEmpty());
        assertTrue(configuration.getXMLDeclarationProcessors(TemplateMode.HTML).isEmpty());
        assertTrue(configuration.getPreProcessors(TemplateMode.HTML).isEmpty());
        assertTrue(configuration.getPostProcessors(TemplateMode.HTML).isEmpty());
    }


    @Test
    void configuredCollectionsAreCopiedAndExposedAsUnmodifiable() {

        final TestPlainDialect firstDialect = new TestPlainDialect("first");
        final TestPlainDialect secondDialect = new TestPlainDialect("second");

        final LinkedHashSet<DialectConfiguration> source = new LinkedHashSet<DialectConfiguration>();
        source.add(new DialectConfiguration(firstDialect));
        source.add(new DialectConfiguration(secondDialect));

        final DialectSetConfiguration configuration = DialectSetConfiguration.build(source);

        source.clear();

        assertEquals(2, configuration.getDialectConfigurations().size());
        assertEquals(2, configuration.getDialects().size());
        assertEquals(Arrays.asList(firstDialect, secondDialect), new ArrayList<IDialect>(configuration.getDialects()));

        assertThrows(
                UnsupportedOperationException.class,
                () -> configuration.getDialectConfigurations().add(new DialectConfiguration(firstDialect)));
        assertThrows(
                UnsupportedOperationException.class,
                () -> configuration.getDialects().add(firstDialect));
        assertThrows(
                UnsupportedOperationException.class,
                () -> configuration.getExecutionAttributes().put("key", "value"));
    }


    @Test
    void executionAttributesFromAllDialectsAreMerged() {

        final Object sharedValue = new Object();
        final TestExecutionAttributeDialect first =
                new TestExecutionAttributeDialect("first", map("alpha", Integer.valueOf(1), "shared", sharedValue));
        final TestExecutionAttributeDialect second =
                new TestExecutionAttributeDialect("second", map("beta", Integer.valueOf(2), "nullable", null));
        final TestExecutionAttributeDialect nullAttributes =
                new TestExecutionAttributeDialect("null-attributes", null);

        final DialectSetConfiguration configuration =
                DiaphragmTestBuildSupport.build(first, second, nullAttributes);

        assertEquals(3, configuration.getExecutionAttributes().size());
        assertEquals(Integer.valueOf(1), configuration.getExecutionAttribute("alpha"));
        assertEquals(Integer.valueOf(2), configuration.getExecutionAttribute("beta"));
        assertSame(sharedValue, configuration.getExecutionAttribute("shared"));
        assertTrue(configuration.hasExecutionAttribute("nullable"));
        assertNull(configuration.getExecutionAttribute("nullable"));
        assertFalse(configuration.hasExecutionAttribute("missing"));
    }


    @Test
    void conflictingExecutionAttributesAreRejected() {

        final TestExecutionAttributeDialect first =
                new TestExecutionAttributeDialect("first", map("duplicated", "first-value"));
        final TestExecutionAttributeDialect second =
                new TestExecutionAttributeDialect("second", map("duplicated", "second-value"));

        final ConfigurationException exception = assertThrows(
                ConfigurationException.class,
                () -> DiaphragmTestBuildSupport.build(first, second));

        assertEquals(
                "Conflicting execution attribute. Two or more dialects specify an execution attribute " +
                "with the same name \"duplicated\".",
                exception.getMessage());
    }


    @Test
    void singleExpressionObjectFactoryIsUsedDirectly() {

        final TestExpressionObjectFactory factory = new TestExpressionObjectFactory(
                "single", true, setOfStrings("one"));

        final DialectSetConfiguration configuration =
                DiaphragmTestBuildSupport.build(new TestExpressionObjectDialect("single-expression", factory));

        final IExpressionObjectFactory aggregate = configuration.getExpressionObjectFactory();
        assertEquals(setOfStrings("one"), aggregate.getAllExpressionObjectNames());
        assertEquals("single:one", aggregate.buildObject(null, "one"));
        assertTrue(aggregate.isCacheable("one"));
    }


    @Test
    void multipleExpressionObjectFactoriesAreAggregatedAndLaterFactoriesWinDuplicateNames() {

        final TestExpressionObjectFactory first = new TestExpressionObjectFactory(
                "first", true, setOfStrings("a", "shared"));
        final TestExpressionObjectFactory second = new TestExpressionObjectFactory(
                "second", false, setOfStrings("b", "shared"));

        final DialectSetConfiguration configuration = DiaphragmTestBuildSupport.build(
                new TestExpressionObjectDialect("first-expression", first),
                new TestExpressionObjectDialect("second-expression", second),
                new TestExpressionObjectDialect("null-expression", null));

        final IExpressionObjectFactory aggregate = configuration.getExpressionObjectFactory();
        assertEquals(setOfStrings("a", "b", "shared"), aggregate.getAllExpressionObjectNames());
        assertEquals("first:a", aggregate.buildObject(null, "a"));
        assertEquals("second:b", aggregate.buildObject(null, "b"));
        assertEquals("second:shared", aggregate.buildObject(null, "shared"));
        assertNull(aggregate.buildObject(null, "missing"));
        assertTrue(aggregate.isCacheable("a"));
        assertFalse(aggregate.isCacheable("b"));
        assertFalse(aggregate.isCacheable("shared"));
        assertFalse(aggregate.isCacheable("missing"));
    }


