    @Test
    void allProcessorTypesAreCollectedByTemplateMode() {

        final TestElementProcessor element = new TestElementProcessor("element", TemplateMode.HTML, 10);
        final TestTemplateBoundariesProcessor boundaries =
                new TestTemplateBoundariesProcessor("boundaries", TemplateMode.HTML, 20);
        final TestCDATASectionProcessor cdata =
                new TestCDATASectionProcessor("cdata", TemplateMode.HTML, 30);
        final TestCommentProcessor comment =
                new TestCommentProcessor("comment", TemplateMode.HTML, 40);
        final TestDocTypeProcessor docType =
                new TestDocTypeProcessor("doctype", TemplateMode.HTML, 50);
        final TestProcessingInstructionProcessor processingInstruction =
                new TestProcessingInstructionProcessor("processing-instruction", TemplateMode.HTML, 60);
        final TestTextProcessor text = new TestTextProcessor("text", TemplateMode.HTML, 70);
        final TestXMLDeclarationProcessor xmlDeclaration =
                new TestXMLDeclarationProcessor("xml-declaration", TemplateMode.HTML, 80);

        final TestProcessorDialect dialect = new TestProcessorDialect(
                "all-processors", "p", 10,
                processorSet(element, boundaries, cdata, comment, docType, processingInstruction, text, xmlDeclaration));

        final DialectSetConfiguration configuration = DialectSetConfiguration.build(
                dialectConfigurations(new DialectConfiguration("configured", dialect)));

        assertEquals("configured", dialect.getLastRequestedPrefix());

        assertEquals(1, configuration.getElementProcessors(TemplateMode.HTML).size());
        assertEquals(1, configuration.getTemplateBoundariesProcessors(TemplateMode.HTML).size());
        assertEquals(1, configuration.getCDATASectionProcessors(TemplateMode.HTML).size());
        assertEquals(1, configuration.getCommentProcessors(TemplateMode.HTML).size());
        assertEquals(1, configuration.getDocTypeProcessors(TemplateMode.HTML).size());
        assertEquals(1, configuration.getProcessingInstructionProcessors(TemplateMode.HTML).size());
        assertEquals(1, configuration.getTextProcessors(TemplateMode.HTML).size());
        assertEquals(1, configuration.getXMLDeclarationProcessors(TemplateMode.HTML).size());

        assertSame(element, ProcessorConfigurationUtils.unwrap(
                configuration.getElementProcessors(TemplateMode.HTML).iterator().next()));
        assertSame(boundaries, ProcessorConfigurationUtils.unwrap(
                configuration.getTemplateBoundariesProcessors(TemplateMode.HTML).iterator().next()));
        assertSame(cdata, ProcessorConfigurationUtils.unwrap(
                configuration.getCDATASectionProcessors(TemplateMode.HTML).iterator().next()));
        assertSame(comment, ProcessorConfigurationUtils.unwrap(
                configuration.getCommentProcessors(TemplateMode.HTML).iterator().next()));
        assertSame(docType, ProcessorConfigurationUtils.unwrap(
                configuration.getDocTypeProcessors(TemplateMode.HTML).iterator().next()));
        assertSame(processingInstruction, ProcessorConfigurationUtils.unwrap(
                configuration.getProcessingInstructionProcessors(TemplateMode.HTML).iterator().next()));
        assertSame(text, ProcessorConfigurationUtils.unwrap(
                configuration.getTextProcessors(TemplateMode.HTML).iterator().next()));
        assertSame(xmlDeclaration, ProcessorConfigurationUtils.unwrap(
                configuration.getXMLDeclarationProcessors(TemplateMode.HTML).iterator().next()));
    }


    @Test
    void processorSetsAreSeparatedByTemplateMode() {

        final TestTextProcessor htmlText = new TestTextProcessor("html-text", TemplateMode.HTML, 10);
        final TestTextProcessor xmlText = new TestTextProcessor("xml-text", TemplateMode.XML, 10);
        final TestTextProcessor rawText = new TestTextProcessor("raw-text", TemplateMode.RAW, 10);

        final DialectSetConfiguration configuration = DiaphragmTestBuildSupport.build(
                new TestProcessorDialect(
                        "modes", "m", 10, processorSet(htmlText, xmlText, rawText)));

        assertEquals(Collections.singleton(htmlText), unwrapTextProcessors(
                configuration.getTextProcessors(TemplateMode.HTML)));
        assertEquals(Collections.singleton(xmlText), unwrapTextProcessors(
                configuration.getTextProcessors(TemplateMode.XML)));
        assertEquals(Collections.singleton(rawText), unwrapTextProcessors(
                configuration.getTextProcessors(TemplateMode.RAW)));
        assertTrue(configuration.getTextProcessors(TemplateMode.TEXT).isEmpty());
        assertTrue(configuration.getTextProcessors(TemplateMode.JAVASCRIPT).isEmpty());
        assertTrue(configuration.getTextProcessors(TemplateMode.CSS).isEmpty());
    }


    @Test
    void processorsAreSortedByDialectThenProcessorPrecedence() {

        final TestTextProcessor earlyButLowPriority =
                new TestTextProcessor("early-but-low-priority", TemplateMode.HTML, 50);
        final TestTextProcessor earlyAndHighPriority =
                new TestTextProcessor("early-and-high-priority", TemplateMode.HTML, 5);
        final TestTextProcessor late = new TestTextProcessor("late", TemplateMode.HTML, 1);

        final TestProcessorDialect lateDialect = new TestProcessorDialect(
                "late-dialect", "late", 20, processorSet(late));
        final TestProcessorDialect earlyDialect = new TestProcessorDialect(
                "early-dialect", "early", 10, processorSet(earlyButLowPriority, earlyAndHighPriority));

        final DialectSetConfiguration configuration = DiaphragmTestBuildSupport.build(lateDialect, earlyDialect);

        final List<String> orderedNames = new ArrayList<String>();
        for (final ITextProcessor processor : configuration.getTextProcessors(TemplateMode.HTML)) {
            orderedNames.add(ProcessorConfigurationUtils.unwrap(processor).toString());
        }

        assertEquals(
                Arrays.asList("early-and-high-priority", "early-but-low-priority", "late"),
                orderedNames);
    }


    @Test
    void definitionsAreInjectedIntoEveryKindOfProcessor() {

        final TestElementProcessor element = new TestElementProcessor("element", TemplateMode.HTML, 10);
        final TestTemplateBoundariesProcessor boundaries =
                new TestTemplateBoundariesProcessor("boundaries", TemplateMode.HTML, 10);
        final TestCDATASectionProcessor cdata =
                new TestCDATASectionProcessor("cdata", TemplateMode.HTML, 10);
        final TestCommentProcessor comment =
                new TestCommentProcessor("comment", TemplateMode.HTML, 10);
        final TestDocTypeProcessor docType =
                new TestDocTypeProcessor("doctype", TemplateMode.HTML, 10);
        final TestProcessingInstructionProcessor processingInstruction =
                new TestProcessingInstructionProcessor("processing-instruction", TemplateMode.HTML, 10);
        final TestTextProcessor text = new TestTextProcessor("text", TemplateMode.HTML, 10);
        final TestXMLDeclarationProcessor xmlDeclaration =
                new TestXMLDeclarationProcessor("xml-declaration", TemplateMode.HTML, 10);

        final TestPreProcessor preProcessor = new TestPreProcessor(
                TemplateMode.HTML, TestTemplateHandler.class, 10);
        final TestPostProcessor postProcessor = new TestPostProcessor(
                TemplateMode.HTML, TestTemplateHandler.class, 10);

        final TestProcessorDialect processorDialect = new TestProcessorDialect(
                "definitions", "d", 10,
                processorSet(element, boundaries, cdata, comment, docType, processingInstruction, text, xmlDeclaration));
        final TestPrePostDialect prePostDialect = new TestPrePostDialect(
                "pre-post", 10,
                Collections.singleton(preProcessor), Collections.singleton(postProcessor));

        final DialectSetConfiguration configuration =
                DiaphragmTestBuildSupport.build(processorDialect, prePostDialect);

        for (final DefinitionAware processor : Arrays.asList(
                element, boundaries, cdata, comment, docType, processingInstruction, text, xmlDeclaration,
                preProcessor, postProcessor)) {
            assertSame(configuration.getElementDefinitions(), processor.getElementDefinitions());
            assertSame(configuration.getAttributeDefinitions(), processor.getAttributeDefinitions());
        }
    }


    @Test
    void preAndPostProcessorsAreGroupedByModeAndSortedByPrecedence() {

        final TestPreProcessor preLow = new TestPreProcessor(
                TemplateMode.HTML, TestTemplateHandler.class, 20);
        final TestPreProcessor preHigh = new TestPreProcessor(
                TemplateMode.HTML, TestTemplateHandler.class, 5);
        final TestPreProcessor preXml = new TestPreProcessor(
                TemplateMode.XML, TestTemplateHandler.class, 1);

        final TestPostProcessor postLow = new TestPostProcessor(
                TemplateMode.HTML, TestTemplateHandler.class, 30);
        final TestPostProcessor postHigh = new TestPostProcessor(
                TemplateMode.HTML, TestTemplateHandler.class, 3);
        final TestPostProcessor postText = new TestPostProcessor(
                TemplateMode.TEXT, TestTemplateHandler.class, 1);

        final DialectSetConfiguration configuration = DiaphragmTestBuildSupport.build(
                new TestPrePostDialect(
                        "pre-post", 10,
                        processorSet(preLow, preHigh, preXml),
                        processorSet(postLow, postHigh, postText)));

        assertEquals(Arrays.asList(preHigh, preLow), new ArrayList<IPreProcessor>(
                configuration.getPreProcessors(TemplateMode.HTML)));
        assertEquals(Collections.singleton(preXml), configuration.getPreProcessors(TemplateMode.XML));
        assertTrue(configuration.getPreProcessors(TemplateMode.TEXT).isEmpty());

        assertEquals(Arrays.asList(postHigh, postLow), new ArrayList<IPostProcessor>(
                configuration.getPostProcessors(TemplateMode.HTML)));
        assertEquals(Collections.singleton(postText), configuration.getPostProcessors(TemplateMode.TEXT));
        assertTrue(configuration.getPostProcessors(TemplateMode.XML).isEmpty());
    }


