    /*
     * Test helpers.
     */

    private static void assertTemplateModeRequired(final Executable executable) {

        final IllegalArgumentException exception = assertThrows(IllegalArgumentException.class, executable);
        assertEquals("Template mode cannot be null", exception.getMessage());
    }


    private static Set<DialectConfiguration> dialectConfigurations(final DialectConfiguration... configurations) {

        final Set<DialectConfiguration> result = new LinkedHashSet<DialectConfiguration>();
        Collections.addAll(result, configurations);
        return result;
    }


    private static Set<IProcessor> processorSet(final IProcessor... processors) {

        final Set<IProcessor> result = new LinkedHashSet<IProcessor>();
        Collections.addAll(result, processors);
        return result;
    }


    private static Set<IPreProcessor> processorSet(final IPreProcessor... processors) {

        final Set<IPreProcessor> result = new LinkedHashSet<IPreProcessor>();
        Collections.addAll(result, processors);
        return result;
    }


    private static Set<IPostProcessor> processorSet(final IPostProcessor... processors) {

        final Set<IPostProcessor> result = new LinkedHashSet<IPostProcessor>();
        Collections.addAll(result, processors);
        return result;
    }


    private static Set<String> setOfStrings(final String... values) {

        final Set<String> result = new LinkedHashSet<String>();
        Collections.addAll(result, values);
        return result;
    }


    private static Map<String, Object> map(final Object... keyValues) {

        final Map<String, Object> result = new LinkedHashMap<String, Object>();
        for (int i = 0; i < keyValues.length; i += 2) {
            result.put((String) keyValues[i], keyValues[i + 1]);
        }
        return result;
    }


    private static Set<ITextProcessor> unwrapTextProcessors(final Set<ITextProcessor> processors) {

