    /*
     * A helper that keeps the tests focused on the target class when all they need is a
     * DialectSetConfiguration built from plain dialects.
     */
    private static final class DiaphragmTestBuildSupport {

        private DiaphragmTestBuildSupport() {
            super();
        }

        static DialectSetConfiguration build(final IDialect... dialects) {
            final Set<DialectConfiguration> configurations = new LinkedHashSet<DialectConfiguration>();
            for (final IDialect dialect : dialects) {
                configurations.add(new DialectConfiguration(dialect));
            }
            return DialectSetConfiguration.build(configurations);
        }
    }




