/**
 * Tests for {@link ProcessorTemplateHandler}.
 *
 * <p>The handler sits at the centre of the engine's event dispatch. Most tests therefore use the
 * public template-engine processing API and a small test dialect. This exercises the handler exactly
 * as it is used in production while keeping every assertion deterministic and independent.</p>
 */
public class ProcessorTemplateHandlerTests {


    private static final TemplateMode MODE = TemplateMode.XML;


    @Test
    public void setContextRejectsNullContext() {

        final ProcessorTemplateHandler handler = new ProcessorTemplateHandler();

        final IllegalArgumentException exception =
                assertThrows(IllegalArgumentException.class, () -> handler.setContext(null));

        assertEquals("Context cannot be null", exception.getMessage());

    }


    @Test
    public void textProcessorCanRewriteText() {

        final IProcessor processor = new AbstractTextProcessor(MODE, 10) {
            @Override
            protected void doProcess(final ITemplateContext context, final IText text,
                    final ITextStructureHandler structureHandler) {
                if ("hello".equals(text.getText())) {
                    structureHandler.setText("goodbye");
                }
            }
        };

        assertEquals("<root>goodbye</root>", process("<root>hello</root>", processor));

    }


    @Test
    public void textReplacementHonoursProcessableFlag() {

        final IProcessor replacement = replacingText("original", "replacement", true);
        final IProcessor rewriter = rewritingText("replacement", "PROCESSED");

        assertEquals("<root>PROCESSED</root>", process("<root>original</root>", replacement, rewriter));

        final IProcessor nonProcessableReplacement = replacingText("original", "replacement", false);
        assertEquals("<root>replacement</root>",
                process("<root>original</root>", nonProcessableReplacement, rewritingText("replacement", "PROCESSED")));

    }


    @Test
    public void textProcessorCanRemoveText() {

        final IProcessor processor = new AbstractTextProcessor(MODE, 10) {
            @Override
            protected void doProcess(final ITemplateContext context, final IText text,
                    final ITextStructureHandler structureHandler) {
                if ("remove".equals(text.getText())) {
                    structureHandler.removeText();
                }
            }
        };

        assertEquals("<root></root>", process("<root>remove</root>", processor));

    }


    @Test
    public void commentProcessorsCanSetContentAndRemoveComment() {

        final IProcessor setContent = new AbstractCommentProcessor(MODE, 10) {
            @Override
            protected void doProcess(final ITemplateContext context, final IComment comment,
                    final ICommentStructureHandler structureHandler) {
                structureHandler.setContent("new");
            }
        };
        assertEquals("<root><!--new--></root>", process("<root><!--old--></root>", setContent));

        final IProcessor remove = new AbstractCommentProcessor(MODE, 10) {
            @Override
            protected void doProcess(final ITemplateContext context, final IComment comment,
                    final ICommentStructureHandler structureHandler) {
                structureHandler.removeComment();
            }
        };
        assertEquals("<root></root>", process("<root><!--old--></root>", remove));

    }


    @Test
    public void cdataSectionProcessorCanSetContent() {

        final IProcessor processor = new AbstractCDATASectionProcessor(MODE, 10) {
            @Override
            protected void doProcess(final ITemplateContext context, final ICDATASection cdataSection,
                    final ICDATASectionStructureHandler structureHandler) {
                assertEquals("old", cdataSection.getContent());
                structureHandler.setContent("new");
            }
        };

        assertEquals("<root><![CDATA[new]]></root>",
                process("<root><![CDATA[old]]></root>", processor));

    }


    @Test
    public void xmlDeclarationDoctypeAndProcessingInstructionCanBeRewritten() {

        final IProcessor declaration = new AbstractXMLDeclarationProcessor(MODE, 10) {
            @Override
            protected void doProcess(final ITemplateContext context, final IXMLDeclaration xmlDeclaration,
                    final IXMLDeclarationStructureHandler structureHandler) {
                assertEquals("1.0", xmlDeclaration.getVersion());
                structureHandler.setXMLDeclaration("xml", "1.1", "ISO-8859-1", "yes");
            }
        };
        final IProcessor docType = new AbstractDocTypeProcessor(MODE, 10) {
            @Override
            protected void doProcess(final ITemplateContext context, final IDocType docType,
                    final IDocTypeStructureHandler structureHandler) {
                structureHandler.setDocType("DOCTYPE", "root", "-//TEST//DTD TEST 1.0//EN", "test.dtd", null);
            }
        };
        final IProcessor instruction = new AbstractProcessingInstructionProcessor(MODE, 10) {
            @Override
            protected void doProcess(final ITemplateContext context,
                    final IProcessingInstruction processingInstruction,
                    final IProcessingInstructionStructureHandler structureHandler) {
                structureHandler.setProcessingInstruction("target2", "new");
            }
        };

        final String result = process(
                "<?xml version=\"1.0\" encoding=\"UTF-8\"?>"
                        + "<!DOCTYPE root SYSTEM \"old.dtd\">"
                        + "<root><?target old?></root>",
                declaration, docType, instruction);

        assertTrue(result.startsWith("<?xml version=\"1.1\" encoding=\"ISO-8859-1\" standalone=\"yes\"?>"), result);
        assertTrue(result.contains("<!DOCTYPE root PUBLIC \"-//TEST//DTD TEST 1.0//EN\" \"test.dtd\">"), result);
        assertTrue(result.contains("<?target2 new?>"), result);

    }


    @Test
    public void templateBoundaryInsertionsCanBeProcessed() {

        final IProcessor boundaries = new AbstractTemplateBoundariesProcessor(MODE, 10) {
            @Override
            public void doProcessTemplateStart(final ITemplateContext context,
                    final org.thymeleaf.model.ITemplateStart templateStart,
                    final ITemplateBoundariesStructureHandler structureHandler) {
                structureHandler.insert("start", true);
            }

            @Override
            public void doProcessTemplateEnd(final ITemplateContext context,
                    final org.thymeleaf.model.ITemplateEnd templateEnd,
                    final ITemplateBoundariesStructureHandler structureHandler) {
                structureHandler.insert("end", true);
            }
        };
        final IProcessor rewriter = new AbstractTextProcessor(MODE, 100) {
            @Override
            protected void doProcess(final ITemplateContext context, final IText text,
                    final ITextStructureHandler structureHandler) {
                if ("start".equals(text.getText())) {
                    structureHandler.setText("[START]");
                } else if ("end".equals(text.getText())) {
                    structureHandler.setText("[END]");
                }
            }
        };

        assertEquals("[START]<root>body</root>[END]",
                process("<root>body</root>", boundaries, rewriter));

    }


    @Test
    public void attributeProcessorCanModifyAttributesAndLimitLocalVariableScope() {

        final IProcessor tagProcessor = new AbstractAttributeTagProcessor(
                MODE, "t", null, false, "mark", true, 10, true) {
            @Override
            protected void doProcess(final ITemplateContext context,
                    final org.thymeleaf.model.IProcessableElementTag tag,
                    final AttributeName attributeName, final String attributeValue,
                    final IElementTagStructureHandler structureHandler) {
                structureHandler.setAttribute("data-mark", attributeValue);
                structureHandler.setLocalVariable("scope", attributeValue);
            }
        };
        final IProcessor textProcessor = new AbstractTextProcessor(MODE, 100) {
            @Override
            protected void doProcess(final ITemplateContext context, final IText text,
                    final ITextStructureHandler structureHandler) {
                final Object scope = context.getVariable("scope");
                if (scope != null) {
                    structureHandler.setText("scoped:" + scope);
                }
            }
        };

        assertEquals("<root><div data-mark=\"v\">scoped:v</div><p>outside</p></root>",
                process("<root><div t:mark=\"v\">inside</div><p>outside</p></root>",
                        tagProcessor, textProcessor));

    }


    @Test
    public void openElementProcessorCanReplaceOrRemoveBody() {

        final IProcessor replaceBody = new AbstractAttributeTagProcessor(
                MODE, "t", null, false, "body", true, 10, true) {
            @Override
            protected void doProcess(final ITemplateContext context,
                    final org.thymeleaf.model.IProcessableElementTag tag,
                    final AttributeName attributeName, final String attributeValue,
                    final IElementTagStructureHandler structureHandler) {
                structureHandler.setBody(attributeValue, true);
            }
        };
        final IProcessor removeBody = new AbstractAttributeTagProcessor(
                MODE, "t", null, false, "empty", true, 10, true) {
            @Override
            protected void doProcess(final ITemplateContext context,
                    final org.thymeleaf.model.IProcessableElementTag tag,
                    final AttributeName attributeName, final String attributeValue,
                    final IElementTagStructureHandler structureHandler) {
                structureHandler.removeBody();
            }
        };
        final IProcessor rewriter = rewritingText("replacement", "PROCESSED");

        assertEquals("<root><div>PROCESSED</div><section></section></root>",
                process("<root><div t:body=\"replacement\">old<strong>child</strong></div>"
                                + "<section t:empty=\"\">old</section></root>",
                        replaceBody, removeBody, rewriter));

    }


    @Test
    public void openElementProcessorCanRemoveTagsOrTheWholeElement() {

        final IProcessor stripTags = new AbstractAttributeTagProcessor(
                MODE, "t", null, false, "strip", true, 10, true) {
