    @Test
    public void openElementProcessorCanReplaceElementAndInsertModels() {

        final IProcessor replace = new AbstractAttributeTagProcessor(
                MODE, "t", null, false, "replace", true, 10, true) {
            @Override
            protected void doProcess(final ITemplateContext context,
                    final org.thymeleaf.model.IProcessableElementTag tag,
                    final AttributeName attributeName, final String attributeValue,
                    final IElementTagStructureHandler structureHandler) {
                structureHandler.replaceWith("replaced", false);
            }
        };
        final IProcessor before = new AbstractAttributeTagProcessor(
                MODE, "t", null, false, "before", true, 10, true) {
            @Override
            protected void doProcess(final ITemplateContext context,
                    final org.thymeleaf.model.IProcessableElementTag tag,
                    final AttributeName attributeName, final String attributeValue,
                    final IElementTagStructureHandler structureHandler) {
                final IModel model = context.getModelFactory().createModel();
                model.add(context.getModelFactory().createText("BEFORE"));
                structureHandler.insertBefore(model);
            }
        };
        final IProcessor after = new AbstractAttributeTagProcessor(
                MODE, "t", null, false, "after", true, 10, true) {
            @Override
            protected void doProcess(final ITemplateContext context,
                    final org.thymeleaf.model.IProcessableElementTag tag,
                    final AttributeName attributeName, final String attributeValue,
                    final IElementTagStructureHandler structureHandler) {
                final IModel model = context.getModelFactory().createModel();
                model.add(context.getModelFactory().createText("AFTER"));
                structureHandler.insertImmediatelyAfter(model, false);
            }
        };

        assertEquals("<root>BEFOREreplaced<span>AFTER</span>tail</root>",
                process("<root><div t:replace=\"\">ignored<em>child</em></div>"
                                + "<span t:before=\"\" t:after=\"\">tail</span></root>",
                        replace, before, after));

    }


