    @Test
    public void elementModelProcessorReceivesAndCanReplaceGatheredModel() {

        final IProcessor processor = new AbstractElementModelProcessor(
                MODE, "t", null, false, "model", true, 10) {
            @Override
            protected void doProcess(final ITemplateContext context, final IModel model,
                    final IElementModelStructureHandler structureHandler) {
                assertTrue(model.size() >= 5);
                for (int i = model.size() - 1; i >= 0; i--) {
                    model.remove(i);
                }
                model.add(context.getModelFactory().createText("MODELLED"));
            }
        };

        assertEquals("<root>MODELLED</root>",
                process("<root><div t:model=\"\"><span>original</span></div></root>", processor));

    }


    @Test
    public void elementModelProcessorCanProcessStandaloneGatheringModel() {

        final IProcessor processor = new AbstractElementModelProcessor(
                MODE, "t", null, false, "model", true, 10) {
            @Override
            protected void doProcess(final ITemplateContext context, final IModel model,
                    final IElementModelStructureHandler structureHandler) {
                assertEquals(1, model.size());
                model.remove(0);
                model.add(context.getModelFactory().createText("MODELLED-STANDALONE"));
            }
        };

        assertEquals("<root>MODELLED-STANDALONE</root>",
                process("<root><br t:model=\"\" /></root>", processor));

