    @Test
    public void throttledProcessingUsesSameHandlerPipeline() {

        final TemplateEngine engine = engine(MODE,
                rewritingText("hello", "goodbye"),
                new AbstractAttributeTagProcessor(MODE, "t", null, false, "mark", true, 10, true) {
                    @Override
                    protected void doProcess(final ITemplateContext context,
                            final org.thymeleaf.model.IProcessableElementTag tag,
                            final AttributeName attributeName, final String attributeValue,
                            final IElementTagStructureHandler structureHandler) {
                        structureHandler.setAttribute("data-mark", attributeValue);
                    }
                });

        final IThrottledTemplateProcessor processor =
                engine.processThrottled("<root><div t:mark=\"v\">hello</div></root>", context());
        final StringWriter writer = new StringWriter();
        processor.processAll(writer);

        assertEquals("<root><div data-mark=\"v\">goodbye</div></root>", writer.toString());
        assertTrue(processor.isFinished());

    }


    @Test
    public void processorExceptionsArePropagatedWithCause() {

        final IProcessor failing = new AbstractTextProcessor(MODE, 10) {
            @Override
            protected void doProcess(final ITemplateContext context, final IText text,
                    final ITextStructureHandler structureHandler) {
                throw new IllegalStateException("boom");
            }
        };

        final TemplateProcessingException exception = assertThrows(TemplateProcessingException.class,
                () -> process("<root>text</root>", failing));

        assertNotNull(exception.getCause());
        assertTrue(exception.getCause() instanceof IllegalStateException);
        assertTrue(exception.getMessage().contains("Error during execution of processor"), exception.getMessage());

    }


    @Test
    public void emptyProcessorSetStillDelegatesOrdinaryEvents() {

        final String result = process("<root><!--comment--><span>text</span></root>");

        assertEquals("<root><!--comment--><span>text</span></root>", result);
        assertFalse(result.contains("t:"));

    }


    private static String process(final String template, final IProcessor... processors) {
        return engine(MODE, processors).process(template, context());
    }


    private static Context context() {
        return new Context(Locale.ENGLISH);
    }


    private static TemplateEngine engine(final TemplateMode mode, final IProcessor... processors) {

        final TemplateEngine engine = new TemplateEngine();
        engine.clearDialects();

        final StringTemplateResolver resolver = new StringTemplateResolver();
        resolver.setTemplateMode(mode);
        resolver.setCacheable(false);
        engine.setTemplateResolver(resolver);

        final Set<IProcessor> processorSet = new LinkedHashSet<IProcessor>(Arrays.asList(processors));
        engine.addDialect("t", new IProcessorDialect() {
            @Override
            public String getPrefix() {
                return "t";
            }

            @Override
            public int getDialectProcessorPrecedence() {
                return 1000;
            }

            @Override
            public Set<IProcessor> getProcessors(final String dialectPrefix) {
                return processorSet;
            }

            @Override
            public String getName() {
                return "test";
            }
        });

        return engine;

    }


    private static IProcessor replacingText(final String from, final String to, final boolean processable) {
        return new AbstractTextProcessor(MODE, 10) {
            @Override
            protected void doProcess(final ITemplateContext context, final IText text,
                    final ITextStructureHandler structureHandler) {
                if (from.equals(text.getText())) {
                    final IModelFactory modelFactory = context.getModelFactory();
                    final IModel replacement = modelFactory.createModel();
                    replacement.add(modelFactory.createText(to));
                    structureHandler.replaceWith(replacement, processable);
                }
            }
        };
    }


    private static IProcessor rewritingText(final String from, final String to) {
        return new AbstractTextProcessor(MODE, 100) {
            @Override
            protected void doProcess(final ITemplateContext context, final IText text,
                    final ITextStructureHandler structureHandler) {
                if (from.equals(text.getText())) {
                    structureHandler.setText(to);
                }
            }
        };
    }

}
